            public void writeInt(int v) throws IOException {
                byteArrayOutputStream.write((v >> 24) & 0xFF);
                byteArrayOutputStream.write((v >> 16) & 0xFF);
                byteArrayOutputStream.write((v >> 8) & 0xFF);
                byteArrayOutputStream.write(v & 0xFF);
            }

