import org.apache.flink.api.common.typeutils.TypeSerializer;
import org.apache.flink.api.java.typeutils.runtime.kryo.KryoSerializer;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import java.lang.reflect.Field;
import java.util.ArrayList;
import java.util.List;

public class PojoTypeInfo_KryoSerializerconfigureKryoLogging_LogTRACEFikaTest {

    @Test
    public void testCreateSerializerTriggersKryoLogging() throws Exception {
        // Create a mock SerializerConfig that forces Kryo
        SerializerConfig config = Mockito.mock(SerializerConfig.class);
        Mockito.when(config.isForceKryoEnabled()).thenReturn(true);
        Mockito.when(config.isForceAvroEnabled()).thenReturn(false);

        // Create a simple POJO class for testing
        class TestPojo {
            public String field;
        }

        // Create PojoField list
        List<PojoField> fields = new ArrayList<>();
        try {
            java.lang.reflect.Field pojoField = TestPojo.class.getDeclaredField("field");
            TypeInformation<?> fieldTypeInfo = TypeInformation.of(String.class);
            fields.add(new PojoField(pojoField, fieldTypeInfo));
        } catch (NoSuchFieldException e) {
            throw new RuntimeException(e);
        }

        // Instantiate PojoTypeInfo using the provided constructor
        PojoTypeInfo<TestPojo> pojoTypeInfo = new PojoTypeInfo<>(TestPojo.class, fields);

        // Force KryoSerializer static initialization to trigger configureKryoLogging
        // This ensures the static block runs before we create the serializer
        Class<?> kryoSerializerClass = KryoSerializer.class;

        // Access the static LOG field and set it to TRACE level
        // This is necessary to make LOG.isTraceEnabled() return true
        Field logField = kryoSerializerClass.getDeclaredField("LOG");
        logField.setAccessible(true);
        org.slf4j.Logger logger = (org.slf4j.Logger) logField.get(null);

        // Create a spy on the logger to control isTraceEnabled()
        org.slf4j.Logger spyLogger = Mockito.spy(logger);
        Mockito.when(spyLogger.isTraceEnabled()).thenReturn(true);
        logField.set(null, spyLogger);

        // Now call the entry point method
        TypeSerializer<TestPojo> serializer = pojoTypeInfo.createSerializer(config);

        // The call above should trigger:
        // 1. createSerializer with config.isForceKryoEnabled() = true
        // 2. new KryoSerializer<>(...) constructor
        // 3. KryoSerializer static initializer (clinit)
        // 4. configureKryoLogging()
        // 5. Log.TRACE() when LOG.isTraceEnabled() returns true
    }
}

