/**
 * Converts the provided configuration data into a format suitable for writing to a file, based
 * on the {@code flattenYaml} flag and the {@code standardYaml} attribute of the configuration
 * object.
 *
 * <p>Only when {@code flattenYaml} is set to {@code false} and the configuration object is
 * standard yaml, a nested YAML format is used. Otherwise, a flat key-value pair format is
 * output.
 *
 * <p>Each entry in the returned list represents a single line that can be written directly to a
 * file.
 *
 * <p>Example input (flat map configuration data):
 *
 * <pre>{@code {
 * "parent.child": "value1",
 * "parent.child2": "value2"
 * }}</pre>
 *
 * <p>Example output when {@code flattenYaml} is {@code false} and the configuration object is
 * standard yaml:
 *
 * <pre>{@code parent:
 * child: value1
 * child2: value2}</pre>
 *
 * <p>Otherwise, the Example output is:
 *
 * <pre>{@code parent.child: value1
 * parent.child2: value2}</pre>
 *
 * @param configuration
 * 		The configuration to be converted.
 * @param flattenYaml
 * 		A boolean flag indicating if the configuration data should be output in a
 * 		flattened format.
 * @return A list of strings, where each string represents a line of the file-writable data in
the chosen format.
 */
public static List<String> convertConfigToWritableLines(Configuration configuration, boolean flattenYaml) {
    if (!flattenYaml) {
        return YamlParserUtils.convertAndDumpYamlFromFlatMap(Collections.unmodifiableMap(configuration.confData));
    } else {
        // PATH: Test should invoke the next DelegatingConfiguration.toFileWritableMap(...) [step in execution path]
        Map<String, String> fileWritableMap = configuration.toFileWritableMap();
        return fileWritableMap.entrySet().stream().map(entry -> (entry.getKey() + ": ") + entry.getValue()).collect(Collectors.toList());
    }
}

@Override
public Map<String, String> toFileWritableMap() {
    Map<String, String> map = backingConfig.toFileWritableMap();
    Map<String, String> prefixed = new HashMap<>();
    for (Map.Entry<String, String> entry : map.entrySet()) {
        if (entry.getKey().startsWith(prefix)) {
            String keyWithoutPrefix = entry.getKey().substring(prefix.length());
            prefixed.put(keyWithoutPrefix, YamlParserUtils.toYAMLString(entry.getValue()));
        }
    }
    return prefixed;
}

