package org.apache.flink.api.common.typeutils;

import org.junit.jupiter.api.Test;
import com.esotericsoftware.kryo.Kryo;
import org.apache.flink.api.common.typeutils.CompositeSerializer.PrecomputedParameters;
import org.apache.flink.api.java.typeutils.runtime.ValueSerializer;
import org.apache.flink.types.Value;
import org.apache.flink.util.Preconditions;
import java.lang.reflect.Field;

public class CompositeSerializer_KryoUtilscopy_KryocopyFikaTest {

    @Test
    public void testCopyChain() throws Exception {
        // Create a Kryo instance that will be used in the chain
        Kryo kryo = new Kryo();

        // Create a mock Value object that implements Value interface
        Value mockValue = new Value() {
            @Override
            public void write(org.apache.flink.core.memory.DataOutputView out) {}

            @Override
            public void read(org.apache.flink.core.memory.DataInputView in) {}
        };

        // Create a ValueSerializer instance
        ValueSerializer<Value> valueSerializer = new ValueSerializer<>(Value.class);

        // Create fieldSerializers array with ValueSerializer as the only element
        @SuppressWarnings("unchecked")
        TypeSerializer<Object>[] fieldSerializers = new TypeSerializer[] {valueSerializer};

        // Create PrecomputedParameters with immutableTargetType = false
        // Using reflection to instantiate PrecomputedParameters since constructor is private
        PrecomputedParameters precomputed = createPrecomputedParameters(false, false, 1, false);

        // Create CompositeSerializer instance using the protected constructor
        CompositeSerializer<Value> serializer = createCompositeSerializer(precomputed, fieldSerializers);

        // Call the entry point method
        serializer.copy(mockValue, mockValue);
    }

    private PrecomputedParameters createPrecomputedParameters(
            boolean immutableTargetType, 
            boolean immutable, 
            int length, 
            boolean stateful) throws Exception {
        // Use reflection to access private constructor
        Class<?> clazz = Class.forName(
            "org.apache.flink.api.common.typeutils.CompositeSerializer$PrecomputedParameters");
        java.lang.reflect.Constructor<?> constructor = clazz.getDeclaredConstructor(
            boolean.class, boolean.class, int.class, boolean.class);
        constructor.setAccessible(true);
        return (PrecomputedParameters) constructor.newInstance(
            immutableTargetType, immutable, length, stateful);
    }

    private CompositeSerializer<Value> createCompositeSerializer(
            PrecomputedParameters precomputed,
            TypeSerializer<Object>[] fieldSerializers) throws Exception {
        // Use reflection to access protected constructor
        java.lang.reflect.Constructor<?> constructor = CompositeSerializer.class.getDeclaredConstructor(
            PrecomputedParameters.class, TypeSerializer[].class);
        constructor.setAccessible(true);
        return (CompositeSerializer<Value>) constructor.newInstance(precomputed, fieldSerializers);
    }
}

