/**
 * Registers a decompression algorithm through a {@link org.apache.flink.api.common.io.compression.InflaterInputStreamFactory} with a file extension
 * for transparent decompression.
 *
 * @param fileExtension
 * 		of the compressed files
 * @param factory
 * 		to create an {@link java.util.zip.InflaterInputStream} that handles the
 * 		decompression format
 */
public static void registerInflaterInputStreamFactory(String fileExtension, InflaterInputStreamFactory<?> factory) {
    synchronized(INFLATER_INPUT_STREAM_FACTORIES) {
        if (INFLATER_INPUT_STREAM_FACTORIES.put(fileExtension, factory) != null) {
            LOG.warn("Overwriting an existing decompression algorithm for \"{}\" files.", fileExtension);
        }
    }
}

