@Override
public TypeSerializerSchemaCompatibility<T> resolveSchemaCompatibility(TypeSerializerSnapshot<T> oldSerializerSnapshot) {
    if (!(oldSerializerSnapshot instanceof PojoSerializerSnapshot)) {
        return TypeSerializerSchemaCompatibility.incompatible();
    }
    PojoSerializerSnapshot<T> previousPojoSerializerSnapshot = ((PojoSerializerSnapshot<T>) (oldSerializerSnapshot));
    final Class<T> previousPojoClass = previousPojoSerializerSnapshot.snapshotData.getPojoClass();
    final LinkedOptionalMap<Field, TypeSerializerSnapshot<?>> fieldSerializerSnapshots = previousPojoSerializerSnapshot.snapshotData.getFieldSerializerSnapshots();
    final LinkedOptionalMap<Class<?>, TypeSerializerSnapshot<?>> registeredSubclassSerializerSnapshots = previousPojoSerializerSnapshot.snapshotData.getRegisteredSubclassSerializerSnapshots();
    final LinkedOptionalMap<Class<?>, TypeSerializerSnapshot<?>> nonRegisteredSubclassSerializerSnapshots = previousPojoSerializerSnapshot.snapshotData.getNonRegisteredSubclassSerializerSnapshots();
    if (previousPojoClass != snapshotData.getPojoClass()) {
        return TypeSerializerSchemaCompatibility.incompatible();
    }
    if (registeredSubclassSerializerSnapshots.hasAbsentKeysOrValues()) {
        return TypeSerializerSchemaCompatibility.incompatible();
    }
    if (nonRegisteredSubclassSerializerSnapshots.hasAbsentKeysOrValues()) {
        return TypeSerializerSchemaCompatibility.incompatible();
    }
    // PATH: Test should invoke the next PojoSerializerSnapshot.getCompatibilityOfPreExistingFields(...) [step in execution path]
    final IntermediateCompatibilityResult<T> preExistingFieldSerializersCompatibility = getCompatibilityOfPreExistingFields(fieldSerializerSnapshots);
    if (preExistingFieldSerializersCompatibility.isIncompatible()) {
        return TypeSerializerSchemaCompatibility.incompatible();
    }
    final IntermediateCompatibilityResult<T> preExistingRegistrationsCompatibility = getCompatibilityOfPreExistingRegisteredSubclasses(registeredSubclassSerializerSnapshots);
    if (preExistingRegistrationsCompatibility.isIncompatible()) {
        return TypeSerializerSchemaCompatibility.incompatible();
    }
    if (newPojoSerializerIsCompatibleAfterMigration(preExistingFieldSerializersCompatibility, preExistingRegistrationsCompatibility, fieldSerializerSnapshots)) {
        return TypeSerializerSchemaCompatibility.compatibleAfterMigration();
    }
    if (newPojoSerializerIsCompatibleWithReconfiguredSerializer(preExistingFieldSerializersCompatibility, preExistingRegistrationsCompatibility, registeredSubclassSerializerSnapshots, nonRegisteredSubclassSerializerSnapshots)) {
        return TypeSerializerSchemaCompatibility.compatibleWithReconfiguredSerializer(constructReconfiguredPojoSerializer(preExistingFieldSerializersCompatibility, registeredSubclassSerializerSnapshots, preExistingRegistrationsCompatibility, nonRegisteredSubclassSerializerSnapshots));
    }
    return TypeSerializerSchemaCompatibility.compatibleAsIs();
}

/**
 * Finds which Pojo fields exists both in the new {@link PojoSerializerSnapshot} as well as in
 * the previous one, and returns an {@link IntermediateCompatibilityResult} of the serializers
 * of those preexisting fields.
 */
private IntermediateCompatibilityResult<T> getCompatibilityOfPreExistingFields(LinkedOptionalMap<Field, TypeSerializerSnapshot<?>> oldFieldSerializerSnapshots) {
    // the present entries dictates the preexisting fields, because removed fields would be
    // represented as absent keys in the optional map.
    final Set<LinkedOptionalMap.KeyValue<Field, TypeSerializerSnapshot<?>>> presentFieldSnapshots = oldFieldSerializerSnapshots.getPresentEntries();
    final ArrayList<TypeSerializerSnapshot<?>> associatedFieldSerializerSnapshots = new ArrayList<>(presentFieldSnapshots.size());
    final ArrayList<TypeSerializerSnapshot<?>> associatedNewFieldSerializerSnapshots = new ArrayList<>(presentFieldSnapshots.size());
    Map<Field, TypeSerializerSnapshot<?>> newFieldSerializerSnapshots = snapshotData.getFieldSerializerSnapshots().unwrapOptionals();
    for (LinkedOptionalMap.KeyValue<Field, TypeSerializerSnapshot<?>> presentFieldEntry : presentFieldSnapshots) {
        TypeSerializerSnapshot<?> associatedNewFieldSerializer = newFieldSerializerSnapshots.get(presentFieldEntry.getKey());
        checkState(associatedNewFieldSerializer != null, "a present field should have its associated new field serializer available.");
        associatedFieldSerializerSnapshots.add(presentFieldEntry.getValue());
        associatedNewFieldSerializerSnapshots.add(associatedNewFieldSerializer);
    }
    // PATH: Test should invoke the next CompositeTypeSerializerUtil.constructIntermediateCompatibilityResult(...) [step in execution path]
    return CompositeTypeSerializerUtil.constructIntermediateCompatibilityResult(associatedNewFieldSerializerSnapshots.toArray(new TypeSerializerSnapshot<?>[associatedNewFieldSerializerSnapshots.size()]), associatedFieldSerializerSnapshots.toArray(new TypeSerializerSnapshot<?>[associatedFieldSerializerSnapshots.size()]));
}

/**
 * Constructs an {@link IntermediateCompatibilityResult} with the given array of nested
 * serializers and their corresponding serializer snapshots.
 *
 * <p>This result is considered "intermediate", because the actual final result is not yet built
 * if it isn't defined. This is the case if the final result is supposed to be {@link TypeSerializerSchemaCompatibility#compatibleWithReconfiguredSerializer(TypeSerializer)},
 * where construction of the reconfigured serializer instance should be done by the caller.
 *
 * <p>For other cases, i.e. {@link TypeSerializerSchemaCompatibility#compatibleAsIs()}, {@link TypeSerializerSchemaCompatibility#compatibleAfterMigration()}, and {@link TypeSerializerSchemaCompatibility#incompatible()}, these results are considered final.
 *
 * @param newNestedSerializerSnapshots
 * 		the new nested serializer snapshots to check for
 * 		compatibility.
 * @param oldNestedSerializerSnapshots
 * 		the associated previous nested serializers' snapshots.
 * @return the intermediate compatibility result of the new nested serializer snapshots.
 */
public static <T> IntermediateCompatibilityResult<T> constructIntermediateCompatibilityResult(TypeSerializerSnapshot<?>[] newNestedSerializerSnapshots, TypeSerializerSnapshot<?>[] oldNestedSerializerSnapshots) {
    Preconditions.checkArgument(newNestedSerializerSnapshots.length == oldNestedSerializerSnapshots.length, "Different number of new serializer snapshots and existing serializer snapshots.");
    TypeSerializer<?>[] nestedSerializers = new TypeSerializer[newNestedSerializerSnapshots.length];
    // check nested serializers for compatibility
    boolean nestedSerializerRequiresMigration = false;
    boolean hasReconfiguredNestedSerializers = false;
    for (int i = 0; i < oldNestedSerializerSnapshots.length; i++) {
        // PATH: Test should invoke the next CompositeTypeSerializerUtil.resolveCompatibility(...) [step in execution path]
        TypeSerializerSchemaCompatibility<?> compatibility = resolveCompatibility(newNestedSerializerSnapshots[i], oldNestedSerializerSnapshots[i]);
        // if any one of the new nested serializers is incompatible, we can just short circuit
        // the result
        if (compatibility.isIncompatible()) {
            return IntermediateCompatibilityResult.definedIncompatibleResult();
        }
        if (compatibility.isCompatibleAfterMigration()) {
            nestedSerializerRequiresMigration = true;
        } else if (compatibility.isCompatibleWithReconfiguredSerializer()) {
            hasReconfiguredNestedSerializers = true;
            nestedSerializers[i] = compatibility.getReconfiguredSerializer();
        } else if (compatibility.isCompatibleAsIs()) {
            nestedSerializers[i] = newNestedSerializerSnapshots[i].restoreSerializer();
        } else {
            throw new IllegalStateException("Undefined compatibility type.");
        }
    }
    if (nestedSerializerRequiresMigration) {
        return IntermediateCompatibilityResult.definedCompatibleAfterMigrationResult();
    }
    if (hasReconfiguredNestedSerializers) {
        return IntermediateCompatibilityResult.undefinedReconfigureResult(nestedSerializers);
    }
    // ends up here if everything is compatible as is
    return IntermediateCompatibilityResult.definedCompatibleAsIsResult(nestedSerializers);
}

