        PojoSerializerSnapshot<TestPojo> pojoSerializerSnapshot = new PojoSerializerSnapshot<>();

        // Create snapshotData with required fields
        PojoSerializerSnapshotData<TestPojo> snapshotData = 
            PojoSerializerSnapshotData.createFrom(
                TestPojo.class,
                new Field[0],
                new TypeSerializerSnapshot<?>[0],
                new LinkedHashMap<>(),
                new HashMap<>()
            );

        // Set snapshotData via reflection
        Field snapshotDataField = PojoSerializerSnapshot.class.getDeclaredField("snapshotData");
        snapshotDataField.setAccessible(true);
        snapshotDataField.set(pojoSerializerSnapshot, snapshotData);

